-- Route-level tests that never reach Postgres: they only exercise requests that are rejected (or answered)
-- before any database call, using Snap's in-process test harness.

module Zocalo.Gallery.RoutesSpec(tests) where

import GHC.Conc(newTVarIO)

import Snap.Core(rspStatus, route)
import Snap.Test(delete, get, getResponseBody, postUrlEncoded, RequestBuilder, runHandler, setHeader)

import Test.Framework(Test, testGroup)
import Test.Framework.Providers.HUnit(testCase)
import Test.HUnit(assertBool, (@?=))

import qualified Data.ByteString       as BS
import qualified Data.ByteString.Char8 as BSChar
import qualified Data.Map              as Map

import Zocalo.Gallery.Controller(routes)


type Req = RequestBuilder IO ()

serve :: Req -> IO (Int, ByteString)
serve req =
  do
    moderators <- newTVarIO Map.empty
    teachers   <- newTVarIO Map.empty
    students   <- newTVarIO Map.empty
    response   <- runHandler req $ route $ routes moderators teachers students
    body       <- getResponseBody response
    return (rspStatus response, body)

getReq, postReq, deleteReq :: ByteString -> Req
getReq    path = get path Map.empty
postReq   path = postUrlEncoded path Map.empty
deleteReq path = delete path Map.empty

withAuthHeader :: ByteString -> Req -> Req
withAuthHeader value req = req >> setHeader "Authorization" value

nano :: ByteString
nano = "V1StGXR8_Z5jdHi6B-myT"

gallery :: ByteString -> ByteString
gallery suffix = "/api/galleries/" <> nano <> suffix

-- Every one of these must be refused before touching the database when no credentials are supplied
needsCredentials :: [(ByteString, Req)]
needsCredentials =
  [ ("teacher: new-session"              , postReq   "/api/galleries/teacher/new-session")
  , ("teacher: overview"                 , getReq    "/api/galleries/teacher/overview")
  , ("teacher: who-am-i"                 , getReq    "/api/auth/teacher/who-am-i")
  , ("teacher: export"                   , getReq    $ gallery "/teacher/export")
  , ("teacher: approve"                  , postReq   $ gallery "/teacher/1/approve")
  , ("teacher: reject"                   , postReq   $ gallery "/teacher/1/reject")
  , ("teacher: refresh (no cookie)"      , postReq   "/api/auth/teacher/refresh")
  , ("teacher: logout (no cookie)"       , postReq   "/api/auth/teacher/logout")
  , ("student: upload"                   , postReq   $ gallery "/student/submission")
  , ("student: comment"                  , postReq   $ gallery "/student/1/comment")
  , ("student: refresh (no cookie)"      , postReq   "/api/auth/student/refresh")
  , ("student: logout (no cookie)"       , postReq   "/api/auth/student/logout")
  ]

tests :: Test
tests =
  testGroup "Zocalo.Gallery.Controller (routes, no database)" $
    [ testCase "GET api/version reports the API version" $
        serve (getReq "/api/version") >>= (@?= (200, "2.0.0"))

    , testGroup "requests without credentials are refused with 401" $
        map (\(label, req) -> testCase (BSChar.unpack label) $ fmap fst (serve req) >>= (@?= 401)) needsCredentials

    , testGroup "requests with unusable Authorization headers are refused with 401"
        [ testCase "a bearer token that is not a JWT" $
            fmap fst (serve $ withAuthHeader "Bearer not.a.jwt" $ getReq "/api/galleries/teacher/overview") >>= (@?= 401)
        , testCase "a non-Bearer scheme" $
            fmap fst (serve $ withAuthHeader "Basic dXNlcjpwYXNz" $ getReq "/api/galleries/teacher/overview") >>= (@?= 401)
        , testCase "a student endpoint given a garbage token" $
            fmap fst (serve $ withAuthHeader "Bearer abc" $ postReq $ gallery "/student/submission") >>= (@?= 401)
        ]

    , testGroup "malformed parameters are refused with 422"
        [ testCase "register without any parameters names every missing field" $ do
            (status, body) <- serve $ postReq "/api/auth/teacher/register"
            status @?= 422
            mapM_' (\field -> assertBool (BSChar.unpack field) (field `BS.isInfixOf` body)) ["email", "firstName", "lastName"]
        , testCase "a gallery ID of the wrong length" $
            fmap fst (serve $ getReq "/api/galleries/too-short/student/template-name") >>= (@?= 422)
        , testCase "a confirmation token that is not a 32-byte token" $
            fmap fst (serve $ postReq "/api/auth/teacher/confirm/not-a-token") >>= (@?= 422)
        , testCase "verify-otp without a passcode" $
            fmap fst (serve $ postUrlEncoded "/api/auth/teacher/verify-otp" $ Map.fromList [("email", ["a@b.c"])]) >>= (@?= 422)
        , testCase "a student cannot be created with a blank name" $
            fmap fst (serve $ postUrlEncoded "/api/auth/student/fresh-cookies" $ Map.fromList [("username", [""])]) >>= (@?= 422)
        , testCase "a submission ID that is not a number (suppress)" $
            fmap fst (serve $ withAuthHeader "Bearer abc" $ deleteReq $ gallery "/student/abc") >>= (@?= 422)
        ]
    ]
  where
    mapM_' f xs = traverse f xs >> return ()
